<?php

namespace Controllers\Utils;

use DOMDocument;
use DOMElement;
use DOMNode;
use DOMText;

class Sanitize
{
    /**
     *  Tags allowed in sanitized HTML, with their allowed attributes
     *  These are the tags generated by the application itself (e.g. Label::white(), Label::envtag())
     */
    private const ALLOWED_TAGS = [
        'span'   => ['class', 'style', 'title'],
        'code'   => ['class'],
        'b'      => [],
        'strong' => [],
        'br'     => [],
        'svg'    => ['class', 'style', 'width', 'height', 'viewbox', 'aria-hidden', 'focusable'],
        'path'   => ['d', 'fill'],
    ];

    /**
     *  Tags that are removed along with their content
     */
    private const DROPPED_TAGS = [
        'script', 'style', 'iframe', 'object', 'embed', 'template', 'noscript', 'textarea',
        'title', 'select', 'xmp', 'noembed', 'noframes', 'frameset', 'frame'
    ];

    /**
     *  Sanitize an HTML fragment by keeping only allowed tags and attributes
     *  Disallowed tags are removed but their text content is kept (except for dropped tags)
     *  Attributes that are not allowed are removed
     */
    public static function html(string $html): string
    {
        // A string without any tag cannot contain any HTML element
        if (!str_contains($html, '<')) {
            return $html;
        }

        $document = new DOMDocument();

        // Parse the fragment wrapped in a root element, the XML declaration forces UTF-8 parsing
        $previousErrors = libxml_use_internal_errors(true);
        $document->loadHTML(
            '<?xml encoding="UTF-8"?><div>' . $html . '</div>',
            LIBXML_HTML_NOIMPLIED | LIBXML_HTML_NODEFDTD | LIBXML_NONET
        );
        libxml_clear_errors();
        libxml_use_internal_errors($previousErrors);

        // Retrieve the root element
        $root = null;

        foreach ($document->childNodes as $node) {
            if ($node instanceof DOMElement) {
                $root = $node;
                break;
            }
        }

        // If the fragment could not be parsed, return it fully escaped
        if ($root === null) {
            return htmlspecialchars($html, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        }

        self::cleanNode($root);

        // Return the inner HTML of the root element
        $output = '';

        foreach ($root->childNodes as $node) {
            $output .= $document->saveHTML($node);
        }

        return $output;
    }

    /**
     *  Recursively clean the children of a node
     */
    private static function cleanNode(DOMNode $node): void
    {
        foreach (iterator_to_array($node->childNodes) as $child) {
            // Text nodes are kept as is, they are escaped when saved
            if ($child instanceof DOMText) {
                continue;
            }

            // Remove comments, processing instructions and any other non element node
            if (!$child instanceof DOMElement) {
                $node->removeChild($child);
                continue;
            }

            $tag = strtolower($child->nodeName);

            // Remove dangerous tags along with their content
            if (in_array($tag, self::DROPPED_TAGS, true)) {
                $node->removeChild($child);
                continue;
            }

            // Clean the children of the element first
            self::cleanNode($child);

            // Disallowed tag: replace it by its (already cleaned) children
            if (!array_key_exists($tag, self::ALLOWED_TAGS)) {
                while ($child->firstChild !== null) {
                    $node->insertBefore($child->firstChild, $child);
                }

                $node->removeChild($child);
                continue;
            }

            // Remove all attributes that are not allowed for this tag
            $attributes = [];

            foreach ($child->attributes as $attribute) {
                $attributes[] = $attribute->nodeName;
            }

            foreach ($attributes as $attribute) {
                $name = strtolower($attribute);

                if (!in_array($name, self::ALLOWED_TAGS[$tag], true)) {
                    $child->removeAttribute($attribute);
                    continue;
                }

                if ($name == 'style' and !self::safeStyle($child->getAttribute($attribute))) {
                    $child->removeAttribute($attribute);
                }
            }
        }
    }

    /**
     *  Return true if an inline style only contains safe characters and no external resource
     */
    private static function safeStyle(string $style): bool
    {
        if (!preg_match('/^[a-zA-Z0-9\s#%.,:;()_-]*$/', $style)) {
            return false;
        }

        if (preg_match('/url\s*\(|expression\s*\(|image-set\s*\(/i', $style)) {
            return false;
        }

        return true;
    }
}
